-- 2026-10-25: shorten blog post meta descriptions to <=160 chars (Semrush "Meta description too long").
-- Not a migration. Run once in the Supabase SQL editor (production). Only touches blog_posts.description; updated_at is left alone.
-- Safe to re-run. Raises (and rolls back) if any slug is missing or any description is still over 160 chars afterwards.
begin;

create temporary table _desc_patch (slug text primary key, description text not null) on commit drop;

do $patch$
declare missing int; updated int;
begin
  select count(*) into missing from _desc_patch p left join blog_posts b on b.slug = p.slug where b.slug is null;
  if missing > 0 then raise exception '% slug(s) not found in blog_posts', missing; end if;
  update blog_posts b set description = p.description from _desc_patch p where b.slug = p.slug;
  get diagnostics updated = row_count;
  if updated <> 156 then raise exception 'expected 156 rows, updated %', updated; end if;
  if exists (select 1 from blog_posts b join _desc_patch p using (slug) where length(b.description) > 160) then raise exception 'a description is still over 160 chars'; end if;
end
$patch$;

-- Check: expect 0
select count(*) as still_over_160 from blog_posts where published and length(description) > 160 and slug in (select slug from _desc_patch);

commit;
